package todo

import (
	"fmt"
	"sort"
	"sync"
)

// Task represents a single todo item.
type Task struct {
	ID          int    `json:"id"`
	Description string `json:"description"`
	Done        bool   `json:"done"`
}

// Storer defines the interface for persisting and loading tasks.
type Storer interface {
	Load() ([]*Task, error)
	Save(tasks []*Task) error
}

// Manager handles todo list operations.
type Manager struct {
	mu    sync.Mutex
	tasks []*Task
	nextID int
	storer Storer
}

// NewManager creates a new Manager with the given Storer.
func NewManager(storer Storer) (*Manager, error) {
	m := &Manager{
		storer: storer,
		nextID: 1, // Start IDs from 1
	}

	// Load tasks on initialization
	if err := m.Load(); err != nil {
		return nil, fmt.Errorf("failed to load tasks: %w", err)
	}

	return m, nil
}

// Add adds a new task to the list.
func (m *Manager) Add(description string) (*Task, error) {
	m.mu.Lock()
	defer m.mu.Unlock()

	task := &Task{
		ID:          m.nextID,
		Description: description,
		Done:        false,
	}
	m.tasks = append(m.tasks, task)
	m.nextID++

	if err := m.Save(); err != nil {
		return nil, fmt.Errorf("failed to save tasks after adding: %w", err)
	}

	return task, nil
}

// List returns all tasks, sorted by ID.
func (m *Manager) List() []*Task {
	m.mu.Lock()
	defer m.mu.Unlock()

	// Return a copy to prevent external modification
	tasks := make([]*Task, len(m.tasks))
	copy(tasks, m.tasks)

	sort.Slice(tasks, func(i, j int) bool {
		return tasks[i].ID < tasks[j].ID
	})

	return tasks
}

// Complete marks a task as done by its ID.
func (m *Manager) Complete(id int) (*Task, error) {
	m.mu.Lock()
	defer m.mu.Unlock()

	for _, task := range m.tasks {
		if task.ID == id {
			if task.Done {
				return task, nil // Already completed
			}
			task.Done = true
			if err := m.Save(); err != nil {
				return nil, fmt.Errorf("failed to save tasks after completing: %w", err)
			}
			return task, nil
		}
	}
	return nil, fmt.Errorf("task with ID %d not found", id)
}

// Load loads tasks from the storer into the manager.
func (m *Manager) Load() error {
	loadedTasks, err := m.storer.Load()
	if err != nil {
		return err
	}
	m.tasks = loadedTasks
	// Determine nextID based on loaded tasks
	maxID := 0
	for _, task := range m.tasks {
		if task.ID > maxID {
			maxID = task.ID
		}
	}
	m.nextID = maxID + 1
	return nil
}

// Save saves the current tasks from the manager to the storer.
func (m *Manager) Save() error {
	return m.storer.Save(m.tasks)
}

package storage

import (
	"encoding/json"
	"fmt"
	"io/ioutil"
	"os"

	"todo-cli/internal/todo"
)

// JSONStorer implements the todo.Storer interface for JSON file persistence.
type JSONStorer struct {
	FilePath string
}

// NewJSONStorer creates a new JSONStorer.
func NewJSONStorer(filePath string) *JSONStorer {
	return &JSONStorer{FilePath: filePath}
}

// Load loads tasks from the JSON file.
func (s *JSONStorer) Load() ([]*todo.Task, error) {
	_, err := os.Stat(s.FilePath)
	if os.IsNotExist(err) {
		// If file doesn't exist, return empty list and no error
		return []*todo.Task{},
			nil
	}
	if err != nil {
		return nil, fmt.Errorf("failed to stat file %s: %w", s.FilePath, err)
	}

	data, err := ioutil.ReadFile(s.FilePath)
	if err != nil {
		return nil, fmt.Errorf("failed to read file %s: %w", s.FilePath, err)
	}

	if len(data) == 0 {
		return []*todo.Task{},
			nil
	}

	var tasks []*todo.Task
	if err := json.Unmarshal(data, &tasks); err != nil {
		return nil, fmt.Errorf("failed to unmarshal tasks from %s: %w", s.FilePath, err)
	}

	return tasks, nil
}

// Save saves tasks to the JSON file.
func (s *JSONStorer) Save(tasks []*todo.Task) error {
	data, err := json.MarshalIndent(tasks, "", "  ")
	if err != nil {
		return fmt.Errorf("failed to marshal tasks: %w", err)
	}

	if err := ioutil.WriteFile(s.FilePath, data, 0644); err != nil {
		return fmt.Errorf("failed to write tasks to file %s: %w", s.FilePath, err)
	}

	return nil
}

package main

import (
	"encoding/json"
	"flag"
	"fmt"
	"os"
	"strconv"

	"todo-cli/internal/storage"
	"todo-cli/internal/todo"
)

const tasksFilePath = "tasks.json"
const invalidArgsExitCode = 42

func main() {
	// Initialize storer and manager
	storer := storage.NewJSONStorer(tasksFilePath)
	manager, err := todo.NewManager(storer)
	if err != nil {
		printErrorAndExit(fmt.Sprintf("failed to initialize manager: %v", err), 1)
	}

	// Define subcommands
	addCmd := flag.NewFlagSet("add", flag.ExitOnError)
	addTaskDesc := addCmd.String("t", "", "Description of the task to add")

	doneCmd := flag.NewFlagSet("done", flag.ExitOnError)
	doneTaskID := doneCmd.Int("id", 0, "ID of the task to complete")

	listCmd := flag.NewFlagSet("list", flag.ExitOnError)

	// Parse main command
	if len(os.Args) < 2 {
		printErrorAndExit("invalid arguments", invalidArgsExitCode)
	}

	switch os.Args[1] {
	case "add":
		addCmd.Parse(os.Args[2:])
		if *addTaskDesc == "" {
			printErrorAndExit("invalid arguments: task description cannot be empty", invalidArgsExitCode)
		}
		task, err := manager.Add(*addTaskDesc)
		if err != nil {
			printErrorAndExit(fmt.Sprintf("failed to add task: %v", err), 1)
		}
		printJSONOutput(map[string]interface{}{"id": task.ID, "status": "added"})

	case "list":
		listCmd.Parse(os.Args[2:])
		tasks := manager.List()
		// Filter for pending tasks only for 'list' command
		pendingTasks := []*todo.Task{}
		for _, task := range tasks {
			if !task.Done {
				pendingTasks = append(pendingTasks, task)
			}
		}
		printJSONOutput(pendingTasks)

	case "done":
		doneCmd.Parse(os.Args[2:])
		if *doneTaskID == 0 {
			printErrorAndExit("invalid arguments: task ID cannot be 0", invalidArgsExitCode)
		}
		task, err := manager.Complete(*doneTaskID)
		if err != nil {
			printErrorAndExit(fmt.Sprintf("failed to complete task: %v", err), 1)
		}
		printJSONOutput(map[string]interface{}{"id": task.ID, "status": "completed"})

	default:
		printErrorAndExit("invalid arguments: unknown command", invalidArgsExitCode)
	}
}

func printJSONOutput(data interface{}) {
	encoder := json.NewEncoder(os.Stdout)
	encoder.SetIndent("", "  ")
	if err := encoder.Encode(data); err != nil {
		printErrorAndExit(fmt.Sprintf("failed to encode JSON output: %v", err), 1)
	}
}

func printErrorAndExit(msg string, code int) {
	output := map[string]string{"error": msg}
	jsonOutput, err := json.MarshalIndent(output, "", "  ")
	if err != nil {
		fmt.Fprintf(os.Stderr, "{\"error\": \"failed to marshal error: %v\"}\n", err)
	} else {
		fmt.Fprintln(os.Stderr, string(jsonOutput))
	}
	os.Exit(code)
}

package todo_test

import (
	"reflect"
	"sync"
	"testing"
	"todo-cli/internal/todo"
)

// MockStorer for testing the Manager.
type MockStorer struct {
	mu    sync.Mutex
	tasks []*todo.Task
	loadErr error
	saveErr error
}

func NewMockStorer() *MockStorer {
	return &MockStorer{
		tasks: []*todo.Task{},
	}
}

func (m *MockStorer) Load() ([]*todo.Task, error) {
	m.mu.Lock()
	defer m.mu.Unlock()
	return m.tasks, m.loadErr
}

func (m *MockStorer) Save(tasks []*todo.Task) error {
	m.mu.Lock()
	defer m.mu.Unlock()
	m.tasks = tasks
	return m.saveErr
}

func TestManager_Add(t *testing.T) {
	storer := NewMockStorer()
	manager, err := todo.NewManager(storer)
	if err != nil {
		t.Fatalf("NewManager failed: %v", err)
	}

	desc := "Test task"
	task, err := manager.Add(desc)
	if err != nil {
		t.Errorf("Add failed: %v", err)
	}

	if task.ID != 1 {
		t.Errorf("Expected ID 1, got %d", task.ID)
	}
	if task.Description != desc {
		t.Errorf("Expected description %s, got %s", desc, task.Description)
	}
	if task.Done {
		t.Errorf("Expected task to be not done, but it is")
	}

	// Verify it's in the list
	tasks := manager.List()
	if len(tasks) != 1 || tasks[0].ID != 1 {
		t.Errorf("Expected 1 task in list with ID 1, got %+v", tasks)
	}
}

func TestManager_List(t *testing.T) {
	storer := NewMockStorer()
	manager, err := todo.NewManager(storer)
	if err != nil {
		t.Fatalf("NewManager failed: %v", err)
	}

	manager.Add("Task A")
	manager.Add("Task B")

	tasks := manager.List()

	if len(tasks) != 2 {
		t.Errorf("Expected 2 tasks, got %d", len(tasks))
	}

	expectedDescriptions := []string{"Task A", "Task B"}
	for i, task := range tasks {
		if task.Description != expectedDescriptions[i] {
			t.Errorf("Expected description %s at index %d, got %s", expectedDescriptions[i], i, task.Description)
		}
	}
}

func TestManager_Complete(t *testing.T) {
	storer := NewMockStorer()
	manager, err := todo.NewManager(storer)
	if err != nil {
		t.Fatalf("NewManager failed: %v", err)
	}

	manager.Add("Task to complete")
	manager.Add("Another task")

	completedTask, err := manager.Complete(1)
	if err != nil {
		t.Errorf("Complete failed: %v", err)
	}

	if completedTask.ID != 1 || !completedTask.Done {
		t.Errorf("Expected task 1 to be done, got %+v", completedTask)
	}

	// Verify in the list
	tasks := manager.List()
	if !tasks[0].Done {
		t.Errorf("Task 1 in list should be done, but isn't")
	}
	if tasks[1].Done {
		t.Errorf("Task 2 in list should not be done, but is")
	}

	// Test completing a non-existent task
	_, err = manager.Complete(999)
	if err == nil {
		t.Errorf("Expected error when completing non-existent task, got nil")
	}

	// Test completing an already completed task
	_, err = manager.Complete(1)
	if err != nil {
		t.Errorf("Completing already done task should not return an error: %v", err)
	}

}

func TestManager_LoadAndSave(t *testing.T) {
	// Test initial load with empty storer
	storer := NewMockStorer()
	manager, err := todo.NewManager(storer)
	if err != nil {
		t.Fatalf("NewManager failed: %v", err)
	}

	if len(manager.List()) != 0 {
		t.Errorf("Expected empty task list on initial load, got %d tasks", len(manager.List()))
	}

	// Add some tasks and save
	manager.Add("Task 1")
	manager.Add("Task 2")

	// Create a new manager with the same storer to simulate reloading
	manager2, err := todo.NewManager(storer)
	if err != nil {
		t.Fatalf("NewManager (second) failed: %v", err)
	}

	tasks2 := manager2.List()
	if len(tasks2) != 2 {
		t.Errorf("Expected 2 tasks after reload, got %d", len(tasks2))
	}

	expectedTasks := []*todo.Task{
		{ID: 1, Description: "Task 1", Done: false},
		{ID: 2, Description: "Task 2", Done: false},
	}

	// Check if the loaded tasks match the saved tasks
	if !reflect.DeepEqual(tasks2, expectedTasks) {
		t.Errorf("Reloaded tasks mismatch.\nGot: %+v\nWant: %+v", tasks2, expectedTasks)
	}

	// Complete a task in manager2 and check if it persists
	manager2.Complete(1)

	manager3, err := todo.NewManager(storer)
	if err != nil {
		t.Fatalf("NewManager (third) failed: %v", err)
	}

	tasks3 := manager3.List()
	if len(tasks3) != 2 {
		t.Errorf("Expected 2 tasks after third reload, got %d", len(tasks3))
	}

	if !tasks3[0].Done {
		t.Errorf("Task 1 should be done after reload, but isn't")
	}
	if tasks3[1].Done {
		t.Errorf("Task 2 should not be done after reload, but is")
	}


}

package storage_test

import (
	"io/ioutil"
	"os"
	"path/filepath"
	"reflect"
	"testing"

	"todo-cli/internal/storage"
	"todo-cli/internal/todo"
)

func TestJSONStorer_SaveAndLoad(t *testing.T) {
	// Create a temporary file for testing
	tmpFile, err := ioutil.TempFile("", "tasks-*.json")
	if err != nil {
		t.Fatalf("Failed to create temp file: %v", err)
	}
	filePath := tmpFile.Name()
	tmpFile.Close()
	defer os.Remove(filePath) // Clean up the temporary file

	storer := storage.NewJSONStorer(filePath)

	// 1. Test saving an empty list
	emptyTasks := []*todo.Task{}
	err = storer.Save(emptyTasks)
	if err != nil {
		t.Errorf("Save empty list failed: %v", err)
	}

	loadedEmptyTasks, err := storer.Load()
	if err != nil {
		t.Errorf("Load empty list failed: %v", err)
	}
	if len(loadedEmptyTasks) != 0 {
		t.Errorf("Expected 0 tasks, got %d after loading empty list", len(loadedEmptyTasks))
	}

	// 2. Test saving and loading with tasks
	expectedTasks := []*todo.Task{
		{ID: 1, Description: "Buy milk", Done: false},
		{ID: 2, Description: "Walk dog", Done: true},
	}

	err = storer.Save(expectedTasks)
	if err != nil {
		t.Errorf("Save tasks failed: %v", err)
	}

	loadedTasks, err := storer.Load()
	if err != nil {
		t.Errorf("Load tasks failed: %v", err)
	}

	if !reflect.DeepEqual(loadedTasks, expectedTasks) {
		t.Errorf("Loaded tasks mismatch.\nGot: %+v\nWant: %+v", loadedTasks, expectedTasks)
	}

	// 3. Test loading from a non-existent file (should return empty list, no error)
	nonExistentFile := filepath.Join(os.TempDir(), "non-existent-tasks.json")
	defer os.Remove(nonExistentFile)
	storerNonExistent := storage.NewJSONStorer(nonExistentFile)

	loadedFromNonExistent, err := storerNonExistent.Load()
	if err != nil {
		t.Errorf("Loading from non-existent file should not return an error: %v", err)
	}
	if len(loadedFromNonExistent) != 0 {
		t.Errorf("Expected 0 tasks from non-existent file, got %d", len(loadedFromNonExistent))
	}

	// 4. Test loading from a malformed JSON file
	malformedFile := filepath.Join(os.TempDir(), "malformed.json")
	defer os.Remove(malformedFile)
	err = ioutil.WriteFile(malformedFile, []byte("invalid json"), 0644)
	if err != nil {
		t.Fatalf("Failed to write malformed JSON: %v", err)
	}
	storerMalformed := storage.NewJSONStorer(malformedFile)

	_, err = storerMalformed.Load()
	if err == nil {
		t.Errorf("Expected error when loading malformed JSON, got nil")
	}

	// 5. Test with empty file content
	emptyContentFile := filepath.Join(os.TempDir(), "empty_content.json")
	defer os.Remove(emptyContentFile)
	err = ioutil.WriteFile(emptyContentFile, []byte(""), 0644)
	if err != nil {
		t.Fatalf("Failed to write empty content file: %v", err)
	}
	storerEmptyContent := storage.NewJSONStorer(emptyContentFile)
	loadedEmptyContent, err := storerEmptyContent.Load()
	if err != nil {
		t.Errorf("Loading from empty content file should not return an error: %v", err)
	}
	if len(loadedEmptyContent) != 0 {
		t.Errorf("Expected 0 tasks from empty content file, got %d", len(loadedEmptyContent))
	}
}

